'use strict';
const $=id=>document.getElementById(id),cv=$('map'),ctx=cv.getContext('2d'),mini=$('mini'),mc=mini.getContext('2d');
const N=32,KEY='emberhold-rts-alpha-1', sprites={};let W=1,H=1,dpr=1,zoom=1.45,camera={x:16,y:16},selected=new Set(),drag=null,box=null,notice='',noticeUntil=0;
const ART={"farm": "data:image/webp;base64,", "knight": "data:image/webp;base64,", "hall": "data:image/webp;base64,", "quarry": "data:image/webp;base64,", "lumber": "data:image/webp;base64,", "tower": "data:image/webp;base64,", "barracks": "data:image/webp;base64,", "archer": "data:image/webp;base64,", "house": "data:image/webp;base64,", "sword": "data:image/webp;base64,"}; for(const [name,src] of Object.entries(ART)){const im=new Image();im.src=src;sprites[name]=im;}
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), rand=(x,y)=>{let n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)};
function fresh(){let nodes=[];for(let x=2;x<N-2;x++)for(let y=2;y<N-2;y++){if(Math.hypot(x-16,y-16)<6)continue;let r=rand(x,y);if(r<.12)nodes.push({x,y,type:r<.075?'wood':r<.102?'stone':'food',left:180});}nodes.push({x:12,y:14,type:'wood',left:180},{x:19,y:13,type:'stone',left:180},{x:19,y:19,type:'food',left:180});return{res:{gold:150,wood:120,stone:60,food:150},units:[{id:1,type:'villager',x:15,y:18},{id:2,type:'villager',x:16,y:19},{id:3,type:'villager',x:17,y:18},{id:4,type:'sword',x:14,y:16},{id:5,type:'archer',x:14,y:17}],nodes,next:6};}
let S=fresh();try{let a=JSON.parse(localStorage.getItem(KEY));if(a&&Array.isArray(a.units)&&Array.isArray(a.nodes)&&a.res)S=a}catch(e){}for(const u of S.units){u.target=null;u.job=null;u.work=0;}
const COST={house:{wood:30,stone:10},farm:{wood:25,gold:20},barracks:{wood:60,stone:40},tower:{wood:40,stone:60},quarry:{wood:30,gold:40},lumber:{gold:30,stone:5}}; const initialBuildings=()=>[{x:16,y:16,type:'hall'},{x:18,y:16,type:'house'}]; S.buildings=S.buildings||initialBuildings();let placing=null; const afford=t=>Object.entries(COST[t]).every(([k,v])=>S.res[k]>=v); function buildAt(p){let x=Math.round(p.x),y=Math.round(p.y);if(x<1||y<1||x>N-2||y>N-2||S.buildings.some(b=>dist(b,{x,y})<1.8)||S.nodes.some(n=>n.left>0&&dist(n,{x,y})<1.2)||S.units.some(u=>dist(u,{x,y})<1)){say('Choose a clear plot');return;}if(!afford(placing)){say('Not enough resources');return;}for(const [k,v] of Object.entries(COST[placing]))S.res[k]-=v;S.buildings.push({x,y,type:placing});say('Building placed: '+placing);placing=null;save();ui();}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));return true}catch(e){return false}}
function say(t){notice=t;noticeUntil=performance.now()+3500;}
function resize(){let r=cv.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(2,devicePixelRatio||1);cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(cv);resize();
function project(x,y){return{x:W/2+(x-y-camera.x+camera.y)*32*zoom,y:H/2+(x+y-camera.x-camera.y)*16*zoom}}
function unproject(x,y){let a=(x-W/2)/(32*zoom),b=(y-H/2)/(16*zoom);return{x:camera.x+(a+b)/2,y:camera.y+(b-a)/2}}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function ellipse(x,y,rx,ry,fill,stroke){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function img(name,p,h){let i=sprites[name];if(i&&i.complete&&i.naturalWidth){let w=h*i.naturalWidth/i.naturalHeight;ctx.drawImage(i,p.x-w/2,p.y-h,w,h);return true}return false}
function drawNode(n,p){let z=zoom;ellipse(p.x,p.y,13*z,5*z,'#0003');if(n.type==='wood'){ctx.fillStyle='#755038';ctx.fillRect(p.x-3*z,p.y-25*z,6*z,25*z);for(let i=0;i<3;i++){let y=p.y-(i*10+10)*z;poly([{x:p.x-16*z+i*3*z,y},{x:p.x,y:y-29*z},{x:p.x+16*z-i*3*z,y}],['#295e3c','#36794b','#4b9252'][i]);}}else if(n.type==='stone'){poly([{x:p.x-15*z,y:p.y-3*z},{x:p.x-10*z,y:p.y-15*z},{x:p.x+3*z,y:p.y-21*z},{x:p.x+14*z,y:p.y-9*z},{x:p.x+10*z,y:p.y}], '#a8b2ac','#596b62');}else{ellipse(p.x,p.y-6*z,13*z,9*z,'#3b7042');for(let i=0;i<5;i++)ellipse(p.x+(i-2)*4*z,p.y-(5+i%2*5)*z,2.5*z,2.5*z,'#ce7760')}}
function drawUnit(u,p){let z=zoom;ellipse(p.x,p.y,10*z,5*z,'#0004',selected.has(u.id)?'#e2f99a':null);if(u.type==='villager'){ctx.strokeStyle='#382f23';ctx.lineWidth=3*z;ctx.beginPath();ctx.moveTo(p.x-3*z,p.y-9*z);ctx.lineTo(p.x-4*z,p.y);ctx.moveTo(p.x+3*z,p.y-9*z);ctx.lineTo(p.x+4*z,p.y);ctx.stroke();ctx.fillStyle='#9e7948';ctx.beginPath();ctx.moveTo(p.x-7*z,p.y-24*z);ctx.lineTo(p.x+7*z,p.y-24*z);ctx.lineTo(p.x+9*z,p.y-9*z);ctx.lineTo(p.x-9*z,p.y-9*z);ctx.closePath();ctx.fill();ellipse(p.x,p.y-28*z,5.5*z,6*z,'#eac49b');ellipse(p.x,p.y-33*z,7*z,3*z,'#62442a');ctx.strokeStyle='#523924';ctx.lineWidth=2*z;ctx.beginPath();ctx.moveTo(p.x-7*z,p.y-21*z);ctx.lineTo(p.x-11*z,p.y-12*z);ctx.moveTo(p.x+7*z,p.y-21*z);ctx.lineTo(p.x+12*z,p.y-13*z);ctx.stroke();ctx.fillStyle='#cbb17a';ctx.fillRect(p.x-7*z,p.y-13*z,14*z,3*z);}else if(!img(u.type,p,43*z)){ctx.fillStyle='#d5d8cf';ctx.fillRect(p.x-5*z,p.y-25*z,10*z,25*z)}if(selected.has(u.id)){ctx.fillStyle='#17251b';ctx.fillRect(p.x-12*z,p.y-46*z,24*z,4*z);ctx.fillStyle='#a7df70';ctx.fillRect(p.x-12*z,p.y-46*z,24*z,4*z)}if(u.job&&u.work>0){ctx.fillStyle='#fff0a6';ctx.font=`${11*z}px sans-serif`;ctx.textAlign='center';ctx.fillText('Gathering',p.x,p.y-48*z)}}
function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#263f2b';ctx.fillRect(0,0,W,H);for(let x=0;x<N;x++)for(let y=0;y<N;y++){let p=project(x,y);if(p.x< -70*zoom||p.x>W+70*zoom||p.y< -35*zoom||p.y>H+35*zoom)continue;let r=rand(x,y),g=99+Math.floor(r*22);poly([project(x-.5,y-.5),project(x+.5,y-.5),project(x+.5,y+.5),project(x-.5,y+.5)],`rgb(${g-25},${g+25},${g-43})`,'#365e3610');if(r>.65){ctx.fillStyle='#d6db8b33';ctx.fillRect(p.x,p.y,2*zoom,2*zoom)}}let all=[...S.buildings.map(o=>({...o,kind:'building'})),...S.nodes.filter(n=>n.left>0).map(o=>({...o,kind:'node'})),...S.units.map(o=>({...o,kind:'unit'}))];all.sort((a,b)=>a.x+a.y-b.x-b.y);for(let o of all){let p=project(o.x,o.y);if(o.kind==='node')drawNode(o,p);else if(o.kind==='building'){ellipse(p.x,p.y,34*zoom,12*zoom,'#0004');img(o.type,p,(o.type==='hall'?145:82)*zoom)}else drawUnit(o,p)}if(box){ctx.strokeStyle='#e6fca1';ctx.fillStyle='#d5ff7720';ctx.fillRect(box.x,box.y,box.w,box.h);ctx.strokeRect(box.x,box.y,box.w,box.h)}mc.fillStyle='#45673c';mc.fillRect(0,0,140,84);for(const n of S.nodes)if(n.left>0){mc.fillStyle=n.type==='wood'?'#234b30':'#c1b589';mc.fillRect(n.x/N*140,n.y/N*84,2,2)}for(const u of S.units){mc.fillStyle=selected.has(u.id)?'#fff5a2':'#f4c367';mc.fillRect(u.x/N*140,u.y/N*84,3,3)}mc.strokeStyle='#f5df9b';mc.strokeRect(camera.x/N*140-10,camera.y/N*84-7,20,14)}
function ui(){ $('resources').innerHTML=['gold','wood','stone','food'].map(k=>`<span>${k.toUpperCase()} <b>${Math.floor(S.res[k])}</b></span>`).join('');let us=S.units.filter(u=>selected.has(u.id));$('selection').textContent=us.length?`${us.length} selected · ${us.filter(u=>u.type==='villager').length} villagers`:'No unit selected';$('detail').textContent=us.length?'Click ground to move. Villagers can click trees, rocks or bushes to gather.':'Select a unit, or drag a box around several units.';$('hint').textContent=performance.now()<noticeUntil?notice:'Click unit → click destination · drag empty ground to select · right-drag to pan';$('train').disabled=S.res.food<30||S.units.length>=30; $('build').textContent=placing?'Cancel '+placing:'Build'; $('buildType').disabled=!!placing;}
function choose(ids,add=false){if(!add)selected.clear();ids.forEach(id=>selected.add(id));ui()}
function order(p,node){let us=S.units.filter(u=>selected.has(u.id));us.forEach((u,i)=>{u.job=node&&u.type==='villager'?{x:node.x,y:node.y}:null;u.work=0;let offset=us.length>1?(i-(us.length-1)/2)*.55:0;u.target={x:clamp(p.x+offset,1,N-2),y:clamp(p.y+(node ? .7 : 0),1,N-2)}});say(node?'Gather command issued to villagers':'Move command issued');}
function click(x,y,shift){let p=unproject(x,y);if(placing){buildAt(p);return}let u=S.units.find(u=>{let a=project(u.x,u.y);return Math.abs(a.x-x)<15*zoom&&y>a.y-44*zoom&&y<a.y+8*zoom});if(u){if(shift&&selected.has(u.id))selected.delete(u.id);else choose([u.id],shift);return}if(selected.size){let n=S.nodes.find(n=>n.left>0&&dist(n,p)<.9)||S.nodes.find(n=>{let a=project(n.x,n.y);return n.left>0&&Math.abs(a.x-x)<13*zoom&&y>a.y-30*zoom&&y<a.y+5*zoom});order(n||p,n)}else choose([])}
cv.oncontextmenu=e=>e.preventDefault();cv.onpointerdown=e=>{cv.setPointerCapture(e.pointerId);drag={x:e.offsetX,y:e.offsetY,button:e.button,cx:camera.x,cy:camera.y,shift:e.shiftKey};};cv.onpointermove=e=>{if(!drag)return;let dx=e.offsetX-drag.x,dy=e.offsetY-drag.y;if(drag.button===2||drag.button===1){camera.x=clamp(drag.cx-(dx/(32*zoom)+dy/(16*zoom))/2,0,N);camera.y=clamp(drag.cy-(-dx/(32*zoom)+dy/(16*zoom))/2,0,N)}else if(Math.hypot(dx,dy)>7)box={x:drag.x,y:drag.y,w:dx,h:dy};};cv.onpointerup=e=>{if(!drag)return;if(box){let x1=Math.min(box.x,box.x+box.w),x2=Math.max(box.x,box.x+box.w),y1=Math.min(box.y,box.y+box.h),y2=Math.max(box.y,box.y+box.h);choose(S.units.filter(u=>{let p=project(u.x,u.y);return p.x>=x1&&p.x<=x2&&p.y>=y1&&p.y<=y2}).map(u=>u.id),drag.shift)}else if(drag.button===0)click(e.offsetX,e.offsetY,e.shiftKey);drag=null;box=null};cv.onpointercancel=()=>{drag=null;box=null};cv.onwheel=e=>{e.preventDefault();zoom=clamp(zoom*(e.deltaY<0?1.12:.89),.55,2.1) };$('plus').onclick=()=>zoom=clamp(zoom+.2,.55,2.1);$('minus').onclick=()=>zoom=clamp(zoom-.2,.55,2.1);$('home').onclick=()=>{camera={x:16,y:16};zoom=1.45};mini.onclick=e=>{let r=mini.getBoundingClientRect();camera={x:clamp((e.clientX-r.left)/r.width*N,0,N),y:clamp((e.clientY-r.top)/r.height*N,0,N)}};$('workers').onclick=()=>choose(S.units.filter(u=>u.type==='villager').map(u=>u.id));$('army').onclick=()=>choose(S.units.filter(u=>u.type!=='villager').map(u=>u.id));$('stop').onclick=()=>S.units.filter(u=>selected.has(u.id)).forEach(u=>{u.target=null;u.job=null;u.work=0});$('train').onclick=()=>{if(S.res.food>=30&&S.units.length<30){S.res.food-=30;S.units.push({id:S.next++,type:'villager',x:17+Math.random(),y:17+Math.random()});ui()}};$('save').onclick=()=>say(save()?'Realm saved':'Save failed');$('reset').onclick=()=>{if(confirm('Reset RTS prototype progress? Classic game is unaffected.')){S=fresh();S.buildings=initialBuildings();placing=null;selected.clear();save();ui()}};
$('build').onclick=()=>{if(placing){placing=null;say('Construction cancelled')}else{placing=$('buildType').value;say('Click clear ground to place '+placing)}ui()}; let last=performance.now(),elapsed=0;function frame(now){let dt=Math.min(.05,(now-last)/1000);last=now;for(const u of S.units){if(u.target){let d=dist(u,u.target),v=dt*(u.type==='villager'?2.2:2.8);if(d<=v){u.x=u.target.x;u.y=u.target.y;u.target=null}else{u.x+=(u.target.x-u.x)/d*v;u.y+=(u.target.y-u.y)/d*v}}else if(u.job){let n=S.nodes.find(n=>n.x===u.job.x&&n.y===u.job.y&&n.left>0);if(!n){u.job=null;u.work=0}else{u.work=(u.work||0)+dt;if(u.work>=1){u.work-=1;let amount=Math.min(3,n.left);n.left-=amount;S.res[n.type]+=amount}}}}draw();elapsed+=dt;if(elapsed>.25){elapsed=0;ui()}requestAnimationFrame(frame)}ui();requestAnimationFrame(frame);setInterval(save,5000);
